// Shared chat-wallpaper catalog — used by both the global picker (Settings →
// Внешний вид) and the per-chat picker (chat header "…" → "Фон чата"). Each
// entry's id maps straight to a ".wallpaper-<id>" class in components.css
// (generated by scripts/gen-doodle.js for the doodle ones); "custom" is the
// odd one out, painted via an inline style instead since it's per-user data,
// not something a static class can express.
export const WALLPAPER_GROUPS = [
  {
    label: "Общие",
    items: [
      { id: "default", label: "По умолчанию" },
      { id: "dots", label: "Точки" },
      { id: "gradient", label: "Градиент" },
      { id: "forest", label: "Лес" },
      { id: "school", label: "Школа" },
      { id: "university", label: "Универ" },
    ],
  },
  {
    label: "Снег",
    items: [
      { id: "snow-1", label: "Снег 1" },
      { id: "snow-2", label: "Снег 2" },
      { id: "snow-3", label: "Снег 3" },
    ],
  },
  {
    label: "Зима",
    items: [
      { id: "winter-1", label: "Зима 1" },
      { id: "winter-2", label: "Зима 2" },
      { id: "winter-3", label: "Зима 3" },
    ],
  },
  {
    label: "Весна",
    items: [
      { id: "spring-1", label: "Весна 1" },
      { id: "spring-2", label: "Весна 2" },
      { id: "spring-3", label: "Весна 3" },
    ],
  },
  {
    label: "Лето",
    items: [
      { id: "summer-1", label: "Лето 1" },
      { id: "summer-2", label: "Лето 2" },
      { id: "summer-3", label: "Лето 3" },
      { id: "summer-4", label: "Лето 4" },
    ],
  },
  {
    label: "Осень",
    items: [
      { id: "autumn-1", label: "Осень 1" },
      { id: "autumn-2", label: "Осень 2" },
      { id: "autumn-3", label: "Осень 3" },
    ],
  },
  {
    label: "Любовь",
    items: [
      { id: "love-1", label: "Любовь 1" },
      { id: "love-2", label: "Любовь 2" },
      { id: "love-3", label: "Любовь 3" },
      { id: "love-4", label: "Любовь 4" },
    ],
  },
  {
    label: "Своё",
    items: [{ id: "custom", label: "Своё фото" }],
  },
];

export const WALLPAPER_IDS = WALLPAPER_GROUPS.flatMap((g) => g.items.map((i) => i.id));
export const WALLPAPER_CLASSES = WALLPAPER_IDS.map((id) => `wallpaper-${id}`);

// Paints `list` (the .message-list element) with the given {id, image}
// wallpaper — shared by chatView.js's global/per-chat applyWallpaper() so
// both stay in sync with WALLPAPER_IDS instead of duplicating this logic.
export function paintWallpaper(list, { id, image } = {}) {
  list.classList.remove(...WALLPAPER_CLASSES);
  if (id === "custom" && image) {
    list.classList.add("wallpaper-custom");
    list.style.backgroundImage = `url(${image})`;
  } else {
    list.style.backgroundImage = "";
    list.classList.add(`wallpaper-${WALLPAPER_IDS.includes(id) ? id : "default"}`);
  }
}
